export type TraceCreate = z.input<typeof TraceCreateSchema>;

export const TraceLinkSchema = z.object({
  id: z.uuid(),
  ownerId: z.uuid(),
  traceId: z.uuid(),
  note: z.string().min(1).nullable(),
  targetBeatId: z.uuid().nullable(),
  targetVersionId: z.uuid().nullable(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
});
export const TraceLinkPublicSchema = TraceLinkSchema;
export const TraceLinkCreateSchema = z.strictObject({
  traceId: z.uuid(),
  note: z.string().min(1).nullish(),
  targetBeatId: z.uuid().nullish(),
  targetVersionId: z.uuid().nullish(),
})
  .refine((value) => exactlyOne(value, ["targetBeatId", "targetVersionId"]), { path: ["target"], error: "Set exactly one target" });
export type TraceLink = z.infer<typeof TraceLinkSchema>;
export type TraceLinkPublic = z.infer<typeof TraceLinkPublicSchema>;
export type TraceLinkCreate = z.input<typeof TraceLinkCreateSchema>;

export const TagSchema = z.object({
  id: z.uuid(),
  ownerId: z.uuid(),
  name: z.string().min(1),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
});
export const TagCreateSchema = z.strictObject({
  name: z.string().min(1),
});
export type Tag = z.infer<typeof TagSchema>;
export type TagCreate = z.input<typeof TagCreateSchema>;

export const TaggingSchema = z.object({
  id: z.uuid(),
  ownerId: z.uuid(),
  tagId: z.uuid(),
  targetAssetId: z.uuid().nullable(),
  targetWorkId: z.uuid().nullable(),
  targetMythId: z.uuid().nullable(),
  targetBeatId: z.uuid().nullable(),
  targetWordingId: z.uuid().nullable(),
  targetVersionId: z.uuid().nullable(),
  targetInterpretationId: z.uuid().nullable(),
  targetTraditionId: z.uuid().nullable(),
  targetMythologyId: z.uuid().nullable(),
  targetFigureId: z.uuid().nullable(),
  targetArchetypeId: z.uuid().nullable(),
  targetTraceId: z.uuid().nullable(),
  targetJournalId: z.uuid().nullable(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
});
export const TaggingCreateSchema = z.strictObject({
  tagId: z.uuid(),
  targetAssetId: z.uuid().nullish(),
  targetWorkId: z.uuid().nullish(),
  targetMythId: z.uuid().nullish(),
  targetBeatId: z.uuid().nullish(),
  targetWordingId: z.uuid().nullish(),
  targetVersionId: z.uuid().nullish(),
  targetInterpretationId: z.uuid().nullish(),
  targetTraditionId: z.uuid().nullish(),
  targetMythologyId: z.uuid().nullish(),
  targetFigureId: z.uuid().nullish(),
  targetArchetypeId: z.uuid().nullish(),
  targetTraceId: z.uuid().nullish(),
  targetJournalId: z.uuid().nullish(),
})
  .refine((value) => exactlyOne(value, ["targetAssetId", "targetWorkId", "targetMythId", "targetBeatId", "targetWordingId", "targetVersionId", "targetInterpretationId", "targetTraditionId", "targetMythologyId", "targetFigureId", "targetArchetypeId", "targetTraceId", "targetJournalId"]), { path: ["target"], error: "Set exactly one target" });
export type Tagging = z.infer<typeof TaggingSchema>;
export type TaggingCreate = z.input<typeof TaggingCreateSchema>;
